plugins {
    id("com.android.application")
}

val appId = providers.gradleProperty("morningstar.appId").get()
val appName = providers.gradleProperty("morningstar.appName").get()
val libName = providers.gradleProperty("morningstar.libName").get()

// The app's launcher icons (ADR 0020): a resource directory generated by
// tools/build-android.sh from the app's Cargo.toml, with mipmap-*/ic_launcher*
// and values/ic_launcher_background.xml. It is not part of this template's
// sources. Building here without the script uses what the script last
// generated, and says so plainly if there is nothing.
val iconResDir: File = providers.gradleProperty("morningstar.resDir")
    .map { file(it) }
    .getOrElse(layout.buildDirectory.dir("generated/morningstar/res").get().asFile)

// The platform services the app opts into (ADR 0038): a comma-separated list
// from the `services` key of its Cargo.toml, passed by tools/build-android.sh.
// Empty for most apps. A service named here adds its sources and its
// dependencies to the host; one that is not named adds nothing to the APK.
//
//   live: live rooms, through LiveKit's Android client (which brings WebRTC).
//         src/live/java is compiled; otherwise src/nolive/java, whose class
//         of the same name refuses every join. Voice and data only.
//   live-video: with `live`, pictures in a live room: the others' cameras
//         and shared screens are shown, and this device's camera can be
//         turned on. Adds the CAMERA permission (ADR 0039).
//   live-screen: with `live`, sharing this device's screen. Adds the
//         foreground-service permissions and two services (ADR 0039).
//   live-background: with `live`, a room joined with a notice goes on
//         behind another app or a locked screen. Adds the foreground
//         service of type microphone, its permissions and the permission
//         to show its notification (ADR 0042).
val knownServices = setOf("live", "live-video", "live-screen", "live-background")
val services: Set<String> = providers.gradleProperty("morningstar.services")
    .getOrElse("")
    .split(',')
    .map { it.trim() }
    .filter { it.isNotEmpty() }
    .toSet()
(services - knownServices).let { unknown ->
    if (unknown.isNotEmpty()) {
        throw GradleException(
            "morningstar.services names $unknown, which this host does not have. " +
                "The services are: $knownServices."
        )
    }
}
val liveRooms = "live" in services
val liveVideo = "live-video" in services
val liveScreen = "live-screen" in services
val liveBackground = "live-background" in services
// Both hold the microphone behind another app, with MorningstarLiveService.
val liveHeld = liveScreen || liveBackground
if ((liveVideo || liveScreen || liveBackground) && !liveRooms) {
    throw GradleException(
        "morningstar.services names live-video, live-screen or live-background without live: " +
            "they are parts of the live room, and need it."
    )
}

// What of LiveKit's manifest this app keeps (see src/main/AndroidManifest.xml):
// a small manifest written here for every build and merged over the main one,
// because which lines it holds depends on the app's services. It is written
// when the build is configured, into the build directory: a `clean` in the
// same Gradle run as a build would delete it, so run them separately.
val serviceManifest: File =
    layout.buildDirectory.file("generated/morningstar/manifest/AndroidManifest.xml").get().asFile
serviceManifest.parentFile.mkdirs()
serviceManifest.writeText(buildString {
    appendLine("""<?xml version="1.0" encoding="utf-8"?>""")
    appendLine("""<manifest xmlns:android="http://schemas.android.com/apk/res/android"""")
    appendLine("""    xmlns:tools="http://schemas.android.com/tools">""")
    val permission = { name: String, remove: Boolean ->
        appendLine(
            """    <uses-permission android:name="android.permission.$name"""" +
                (if (remove) """ tools:node="remove"""" else "") + " />"
        )
    }
    // The camera: asked of the user when it is first turned on. Not a
    // reason to hide the app from a device without one.
    permission("CAMERA", !liveVideo)
    if (liveVideo) {
        for (feature in listOf("camera", "camera.autofocus")) {
            appendLine(
                """    <uses-feature android:name="android.hardware.$feature" android:required="false" />"""
            )
        }
    }
    // Sharing the screen needs a foreground service of type mediaProjection
    // (LiveKit's own), and the room that goes on behind another app needs
    // one of type microphone (MorningstarLiveService).
    // The same microphone service is what lets a room that was joined
    // with a notice go on in the background (ADR 0042); its notification
    // is asked of the user on Android 13 and later.
    permission("FOREGROUND_SERVICE", !liveHeld)
    permission("FOREGROUND_SERVICE_MEDIA_PROJECTION", !liveScreen)
    if (liveHeld) {
        permission("FOREGROUND_SERVICE_MICROPHONE", false)
        permission("POST_NOTIFICATIONS", false)
    }
    if (liveRooms) {
        // The screen goes dark at the ear while the sound is in the
        // earpiece: a proximity wake lock. Granted at install.
        permission("WAKE_LOCK", false)
        // Up to Android 11 a Bluetooth headset is found through the
        // BLUETOOTH permission LiveKit's audio library declares (granted
        // at install; from Android 12 the platform's communication-device
        // API is used and nothing is asked). Not a reason to hide the app
        // from a device without Bluetooth.
        appendLine(
            """    <uses-feature android:name="android.hardware.bluetooth" android:required="false" />"""
        )
    }
    appendLine("    <application>")
    if (liveBackground) {
        // How MorningstarLive knows the app was built for it.
        appendLine(
            """        <meta-data android:name="dev.morningstar.live.background" android:value="true" />"""
        )
    }
    if (liveHeld) {
        // stopWithTask false: the service is told when the app is swiped
        // away (onTaskRemoved) and leaves the room itself.
        appendLine(
            """        <service android:name="dev.morningstar.host.MorningstarLiveService" """ +
                """android:exported="false" android:foregroundServiceType="microphone" """ +
                """android:stopWithTask="false" />"""
        )
    }
    if (!liveScreen) {
        appendLine(
            """        <service android:name="io.livekit.android.room.track.screencapture.ScreenCaptureService" """ +
                """tools:node="remove" />"""
        )
    }
    appendLine("    </application>")
    appendLine("</manifest>")
})

// The ABIs the app's Rust library was built for: the directories
// tools/build-android.sh has just filled under src/main/jniLibs. Native
// libraries that come with a dependency are packaged for these and no
// others. Without this a dependency that ships four ABIs (LiveKit's WebRTC)
// would put all four into an APK whose application exists for one, where
// the other three can never run.
val rustAbis: List<String> = file("src/main/jniLibs")
    .listFiles { entry -> entry.isDirectory }
    ?.map { it.name }
    ?.sorted()
    .orEmpty()

val checkMorningstarIcons = tasks.register("checkMorningstarIcons") {
    val marker = iconResDir.resolve("mipmap-anydpi-v26/ic_launcher.xml")
    doLast {
        if (!marker.isFile) {
            throw GradleException(
                "The app's launcher icons are missing: there is no $marker.\n" +
                    "They are generated from the app's Cargo.toml by tools/build-android.sh " +
                    "(MORNINGSTAR_APP=<package> tools/build-android.sh), which also runs this " +
                    "build. To generate them alone:\n" +
                    "  cargo run -q -p morningstar-devtools --bin morningstar-icon -- " +
                    "<package> --android ${iconResDir}"
            )
        }
    }
}
tasks.named("preBuild") { dependsOn(checkMorningstarIcons) }

android {
    // Namespace of the host's own Java classes; fixed, because the Rust JNI
    // symbols are named after it. The application id is what varies per app.
    namespace = "dev.morningstar.host"
    compileSdk = 36

    defaultConfig {
        applicationId = appId
        // API 24 is the first release where Vulkan 1.0 is part of the platform.
        minSdk = 24
        targetSdk = 36
        versionCode = 1
        versionName = "0.0.1"

        manifestPlaceholders["appName"] = appName
        manifestPlaceholders["libName"] = libName

        if (rustAbis.isNotEmpty()) {
            ndk { abiFilters.addAll(rustAbis) }
        }
    }

    sourceSets["main"].res.directories.add(iconResDir.path)
    // The per-app part of the manifest, merged over the main one in every
    // build type.
    for (buildType in listOf("debug", "release")) {
        sourceSets[buildType].manifest.srcFile(serviceManifest)
    }
    // Exactly one MorningstarLive: the LiveKit one, or the one that refuses.
    if (liveRooms) {
        // MorningstarLive.kt, the host's one Kotlin file (LiveKit's client
        // is called through coroutines).
        sourceSets["main"].kotlin.directories.add("src/live/java")
    } else {
        sourceSets["main"].java.directories.add("src/nolive/java")
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    buildTypes {
        release {
            isMinifyEnabled = false
        }
    }
}

// The Android Gradle plugin compiles Kotlin by itself and, for that, adds
// the Kotlin standard library to every app, used or not: 2.4 MB of classes.
// The host is Java; its one Kotlin file is the live room's. So an app
// without that service ships no Kotlin either. (With the service, the
// plugin's own choice of library stands, which is the one that matches the
// compiler.)
if (!liveRooms) {
    configurations
        .matching { it.name.endsWith("CompileClasspath") || it.name.endsWith("RuntimeClasspath") }
        .configureEach { exclude(group = "org.jetbrains.kotlin", module = "kotlin-stdlib") }
}

dependencies {
    if (liveRooms) {
        // LiveKit's client: the signalling, WebRTC (a native library per
        // ABI) and the audio routing. The version is the newest stable
        // release when this was written (2026-11-03); its own dependencies
        // need JitPack, which settings.gradle.kts adds for this case only.
        implementation("io.livekit:livekit-android:2.30.0")
        // MorningstarLive.kt uses coroutines to call it. LiveKit ships
        // them, but as a runtime dependency, which is not on the compile
        // classpath. The version is the one LiveKit's own dependencies
        // resolve to (it asks for 1.6.0, its livekit-ffi-android for
        // 1.8.1), so this line adds nothing to the APK.
        implementation("org.jetbrains.kotlinx:kotlinx-coroutines-android:1.8.1")
    }
}
